"""Original offline interview practice bank for useful no-network operation."""

from __future__ import annotations

import hashlib
import re
from typing import Any


SOURCE_LABEL = "内置面试高频题型（原创整理）"


def _qa(
    topic: str,
    question: str,
    conclusion: str,
    detail: str,
    points: list[str],
    pitfall: str = "",
    follow_up: str = "",
) -> dict[str, Any]:
    parts = [f"一句话结论：{conclusion}", f"原理拆解：{detail}"]
    parts.append(f"工程示例：{_engineering_example(detail, points)}")
    if points:
        parts.append("回答要点：\n" + "\n".join(f"- {point}" for point in points))
    if pitfall:
        parts.append(f"易错点：\n- {pitfall}")
    if follow_up:
        parts.append(f"面试追问：\n- {follow_up}")
    parts.append(f"来源：{SOURCE_LABEL}")
    normalized = "".join(character.lower() for character in question if character.isalnum())
    key = hashlib.sha256(f"{topic}\0{normalized}".encode("utf-8")).hexdigest()
    return {
        "question": question,
        "answer": "\n\n".join(parts),
        "answer_summary": conclusion,
        "answer_detail": detail,
        "key_points": points,
        "pitfalls": [pitfall] if pitfall else [],
        "follow_ups": [follow_up] if follow_up else [],
        "question_type": "high-frequency",
        "difficulty": "normal",
        "source_label": SOURCE_LABEL,
        "canonical_key": key,
    }


def _engineering_example(detail: str, points: list[str]) -> str:
    clauses = [item.strip(" ；;。") for item in re.split(r"[。；;]", detail) if item.strip()]
    if len(clauses) >= 2:
        return clauses[-1] + "。"
    focus = "、".join(points[:2]) or "关键行为"
    return f"可用最小代码、日志或测试验证“{focus}”，并说明输入、结果和边界条件。"


