def curated_pairs_for_topic(topic: str) -> list[dict[str, Any]]:
    return [dict(pair) for pair in CURATED_INTERVIEW_QA.get(topic, [])]


def curated_question_count() -> int:
    return sum(len(pairs) for pairs in CURATED_INTERVIEW_QA.values())
